6.2 Genus composition across all isolates
A shared palette for phylum, plus a helper that bins a taxonomic rank into its top categories (grouping everything else as "Other") and computes relative composition per sampling site. Plot styling (theme_project(), capit()) and the make_palette() generator live in R/plotting.R, shared with other notebooks in this project.


Show/hide code
phylum_colors &lt;- c(
  "Pseudomonadota" = "#1f78b4",
  "Bacteroidota" = "#ff7f00",
  "Bacillota" = "#33a02c",
  "Deinococcota" = "#e31a1c"
)

composition_by_site &lt;- function(
  df,
  rank_col,
  top_n,
  palette,
  other_color = "grey60"
) {
  top_cats &lt;- df |&gt;
    filter(!is.na(.data[[rank_col]])) |&gt;
    count(.data[[rank_col]], sort = TRUE) |&gt;
    slice_head(n = top_n) |&gt;
    pull(1)

  plot_df &lt;- df |&gt;
    filter(!is.na(location)) |&gt;
    mutate(
      cat = if_else(.data[[rank_col]] %in% top_cats, .data[[rank_col]], "Other")
    ) |&gt;
    count(location, cat) |&gt;
    group_by(location) |&gt;
    mutate(pct = 100 * n / sum(n)) |&gt;
    ungroup() |&gt;
    mutate(cat = factor(cat, levels = c(top_cats, "Other")))

  cat_colors &lt;- c(palette[top_cats], "Other" = other_color)

  ggplot(plot_df, aes(x = location, y = pct, fill = cat)) +
    geom_col(color = "white", linewidth = 0.3) +
    scale_fill_manual(values = cat_colors, name = str_to_title(rank_col)) +
    labs(x = NULL, y = "% of isolates") +
    capit() +
    theme_project() +
    theme(
      legend.position = "right",
      legend.title = element_text(),
      axis.text.x = element_text(angle = 20, hjust = 1)
    )
}




Show/hide code
genus_counts &lt;- classified |&gt; count(genus, sort = TRUE)

top_genus &lt;- genus_counts |&gt; filter(!is.na(genus)) |&gt; slice_head(n = 12)
other_n &lt;- genus_counts |&gt;
  filter(!genus %in% top_genus$genus | is.na(genus)) |&gt;
  summarise(n = sum(n)) |&gt;
  pull(n)

genus_plot_df &lt;- bind_rows(top_genus, tibble(genus = "Other", n = other_n)) |&gt;
  mutate(genus = fct_reorder(genus, n))




Show/hide code
ggplot(genus_plot_df, aes(x = n, y = genus)) +
  geom_col(fill = "#1f78b4") +
  geom_text(aes(label = n), hjust = -0.3, size = 3) +
  labs(x = "Number of isolates", y = NULL) +
  scale_x_continuous(expand = expansion(mult = c(0, 0.1))) +
  capit() +
  theme_project()








Figure 4: Genus composition across all 170 classified isolates. The 12 most abundant genera are shown individually; all remaining genera are pooled as “Other”.

6.5 Relative composition by site — family


Show/hide code
family_cats &lt;- classified |&gt;
  filter(!is.na(family)) |&gt;
  distinct(family) |&gt;
  pull(family)
composition_by_site(
  classified,
  "family",
  top_n = 15,
  palette = make_palette(family_cats)
)








Figure 7: Relative family composition of classified isolates by sampling site. The 15 most abundant families are shown individually; all remaining families are pooled as “Other”.

